import sys

def pr(x):
	sys.stdout.write(str(x) + '\n')

def inp():
	return sys.stdin.readline()
M = 998244353
(k, a, h) = [int(i) for i in inp().split()]
pp = [[], [2], [3, 2], [5, 3, 2], [9, 5, 3, 2], [17, 9, 5, 3, 2]]
pa = [a ** i % M for i in pp[k]]
rgs = [[], [[1, 3]], [[4, 7], [1, 5]], [[16, 21], [6, 13], [1, 9]], [[64, 73], [28, 41], [10, 25], [1, 17]], [[256, 273], [120, 145], [52, 81], [18, 49], [1, 33]]]
rg = rgs[k]
xa = {}
for i in range(1, (1 << k) + 1):
	xa[i * a % M] = i
r = [0] * (k + 1)

def dfs(n, num):
	if n == k:
		x = (h + M - num) % M
		if x in xa:
			r[n] = xa[x]
			if sum(r) == sum(range(1, (1 << k) + 1)):
				return True
	else:
		for i in range(rg[n][0], rg[n][1]):
			r[n] = i
			if dfs(n + 1, (num + i * pa[n]) % M):
				return True
		return False
if not dfs(0, 0):
	pr(-1)
	sys.exit()
if sum(r) != sum(range(1, (1 << k) + 1)):
	pr(-1)
	sys.exit()
res = [pp[k][0]] * (1 << k)
res[r[-1] - 1] = 1
res[r[-2] - 1] = 2
if (r[-1] - 1) // 1 << k - 1 == (r[-2] - 1) // 1 << k - 1:
	pr(-1)
	sys.exit()
for i in range(k - 2, 0, -1):
	t = [1] * (1 << k - i)
	for j in range(1 << k):
		if res[j] != pp[k][0]:
			t[j // (1 << i)] = 0
	r[i] -= sum(((j * 1 << i) + 1 for j in range(len(t)) if t[j]))
	for j in range(len(t)):
		if t[j]:
			x = min(r[i], (1 << i) - 1)
			r[i] -= x
			res[j * (1 << i) + x] = pp[k][i]
	if r[i]:
		pr(-1)
		sys.exit()
print(' '.join((str(i) for i in res)))
